  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  outline: none;
  touch-action: none;
}

.hidden { display: none !important; }
.invisible { opacity: 0 !important; pointer-events: none !important; }

/* ------------------------------ atmosphere ------------------------------ */

