.touch-controls {
  position: fixed;
  inset: 0;
  z-index: 25;
  pointer-events: none;
}
.stick-zone {
  position: absolute;
  left: max(1rem, env(safe-area-inset-left));
  bottom: max(1.2rem, env(safe-area-inset-bottom));
  width: 9rem;
  height: 9rem;
  pointer-events: auto;
  touch-action: none;
  display: flex;
  align-items: center;
  justify-content: center;
}
.stick-base {
  width: 7rem;
  height: 7rem;
  border-radius: 50%;
  border: 1px solid rgba(246, 238, 214, 0.27);
  background: radial-gradient(circle, rgba(247, 238, 213, 0.08) 0%, rgba(40, 53, 34, 0.22) 72%);
  backdrop-filter: blur(3px);
  -webkit-backdrop-filter: blur(3px);
  position: relative;
  box-shadow: inset 0 0 24px rgba(20, 28, 17, 0.22);
}
.stick-base::before, .stick-base::after {
  content: "";
  position: absolute;
  background: rgba(246, 236, 209, 0.12);
}
.stick-base::before { left: 50%; top: 18%; width: 1px; height: 64%; }
.stick-base::after { top: 50%; left: 18%; height: 1px; width: 64%; }
.stick-knob {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 2.85rem;
  height: 2.85rem;
  margin: -1.425rem 0 0 -1.425rem;
  border-radius: 50%;
  background: radial-gradient(circle at 38% 32%, rgba(250, 242, 219, 0.95), rgba(203, 185, 146, 0.82));
  box-shadow: 0 4px 16px rgba(17, 24, 14, 0.28), inset 0 1px 0 rgba(255, 255, 255, 0.65);
  transition: transform 0.05s linear;
  will-change: transform;
}
.touch-buttons {
  position: absolute;
  right: max(1rem, env(safe-area-inset-right));
  bottom: max(1.35rem, env(safe-area-inset-bottom));
  display: flex;
  align-items: flex-end;
  gap: 0.7rem;
  pointer-events: auto;
