.flight-btn svg { width: 1.85rem; height: 1.85rem; }
.flight-btn:active, .flight-btn.pressed { transform: scale(0.93); background: radial-gradient(circle at 40% 32%, rgba(250, 238, 205, 0.55), rgba(60, 77, 48, 0.4)); }
