// Shared deterministic noise & math helpers.
// The valley is generated from the same height field used for flight collision,
// so what you see is what you can land on.

export const clamp = (v, a, b) => Math.min(b, Math.max(a, v));
export const lerp = (a, b, t) => a + (b - a) * t;
export const smoothstep = (a, b, x) => {
  const t = clamp((x - a) / (b - a), 0, 1);
  return t * t * (3 - 2 * t);
};
export const smootherstep = (a, b, x) => {
  const t = clamp((x - a) / (b - a), 0, 1);
  return t * t * t * (t * (t * 6 - 15) + 10);
};
export const damp = (current, target, lambda, dt) =>
  lerp(current, target, 1 - Math.exp(-lambda * dt));

export function mulberry32(seed) {
  let a = seed >>> 0;
  return function () {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function hash2(x, y) {
  let h = Math.imul(x | 0, 374761393) ^ Math.imul(y | 0, 668265263);
  h = Math.imul(h ^ (h >>> 13), 1274126177);
  return ((h ^ (h >>> 16)) >>> 0) / 4294967295;
}

export function valueNoise(x, y) {
  const xi = Math.floor(x);
  const yi = Math.floor(y);
  const xf = x - xi;
  const yf = y - yi;
  const u = xf * xf * (3 - 2 * xf);
  const v = yf * yf * (3 - 2 * yf);
  const a = hash2(xi, yi);
  const b = hash2(xi + 1, yi);
  const c = hash2(xi, yi + 1);
  const d = hash2(xi + 1, yi + 1);
  return lerp(lerp(a, b, u), lerp(c, d, u), v);
}

export function fbm(x, y, octaves = 4, persistence = 0.5, lacunarity = 2.03) {
  let amp = 1;
  let freq = 1;
  let sum = 0;
  let norm = 0;
  for (let i = 0; i < octaves; i++) {
    sum += amp * valueNoise(x * freq, y * freq);
    norm += amp;
    amp *= persistence;
    freq *= lacunarity;
  }
  return sum / norm;
}

export const randRange = (rng, a, b) => a + (b - a) * rng();
export const randPick = (rng, arr) => arr[Math.floor(rng() * arr.length) % arr.length];

export function shortestAngle(from, to) {
  let d = (to - from) % (Math.PI * 2);
  if (d > Math.PI) d -= Math.PI * 2;
  if (d < -Math.PI) d += Math.PI * 2;
  return d;
}

import * as THREE from 'three';
import { mulberry32 } from './utils.js';

export function makeToonGradient(steps = [72, 142, 208, 255]) {
  const data = new Uint8Array(steps.length * 4);
  steps.forEach((v, i) => {
    data[i * 4 + 0] = v;
    data[i * 4 + 1] = v;
    data[i * 4 + 2] = v;
    data[i * 4 + 3] = 255;
  });
  const tex = new THREE.DataTexture(data, steps.length, 1, THREE.RGBAFormat);
  tex.minFilter = THREE.NearestFilter;
  tex.magFilter = THREE.NearestFilter;
  tex.generateMipmaps = false;
  tex.needsUpdate = true;
  return tex;
}

export function makeGlowTexture(size = 128, inner = 'rgba(255,248,220,1)', outer = 'rgba(255,214,140,0)') {
  const c = document.createElement('canvas');
  c.width = c.height = size;
  const ctx = c.getContext('2d');
  const g = ctx.createRadialGradient(size / 2, size / 2, 0, size / 2, size / 2, size / 2);
  g.addColorStop(0, inner);
  g.addColorStop(0.18, inner);
  g.addColorStop(0.45, 'rgba(255,226,160,0.32)');
  g.addColorStop(1, outer);
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, size, size);
  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace;
  return tex;
}

export function makeDotTexture(size = 64) {
  const c = document.createElement('canvas');
  c.width = c.height = size;
  const ctx = c.getContext('2d');
  const g = ctx.createRadialGradient(size / 2, size / 2, 0, size / 2, size / 2, size / 2);
  g.addColorStop(0, 'rgba(255,255,255,1)');
  g.addColorStop(0.35, 'rgba(255,255,255,0.85)');
  g.addColorStop(1, 'rgba(255,255,255,0)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, size, size);
  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace;
  return tex;
}

export function makePetalTexture(size = 64) {
  const c = document.createElement('canvas');
  c.width = c.height = size;
  const ctx = c.getContext('2d');
  ctx.translate(size / 2, size / 2);
  ctx.rotate(-0.5);
  const g = ctx.createLinearGradient(-size * 0.3, 0, size * 0.3, 0);
  g.addColorStop(0, 'rgba(255,238,242,1)');
  g.addColorStop(0.6, 'rgba(255,196,210,1)');
  g.addColorStop(1, 'rgba(246,166,188,0.9)');
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.ellipse(0, 0, size * 0.28, size * 0.14, 0, 0, Math.PI * 2);
  ctx.fill();
  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace;
  return tex;
}

export function makeGrassTexture() {
  const size = 256;
  const c = document.createElement('canvas');
  c.width = c.height = size;
  const ctx = c.getContext('2d');
  ctx.fillStyle = '#cfd4b8';
  ctx.fillRect(0, 0, size, size);
  const rng = mulberry32(99173);
  for (let i = 0; i < 2600; i++) {
    const x = rng() * size;
    const y = rng() * size;
    const h = 1 + rng() * 5;
    const shade = 170 + Math.floor(rng() * 70);
    const tint = rng() < 0.2 ? 235 : shade;
    ctx.strokeStyle = `rgba(${tint - 14},${tint},${tint - 40},${0.16 + rng() * 0.22})`;
    ctx.lineWidth = 0.7 + rng() * 0.9;
    ctx.beginPath();
    ctx.moveTo(x, y);
    ctx.lineTo(x + (rng() - 0.5) * 3, y - h);
    ctx.stroke();
  }
  for (let i = 0; i < 40; i++) {
    const x = rng() * size;
    const y = rng() * size;
    const r = 8 + rng() * 34;
    const g = ctx.createRadialGradient(x, y, 0, x, y, r);
    const bright = rng() < 0.5;
    g.addColorStop(0, bright ? 'rgba(240,238,196,0.10)' : 'rgba(120,140,88,0.10)');
    g.addColorStop(1, 'rgba(200,200,160,0)');
    ctx.fillStyle = g;
    ctx.fillRect(x - r, y - r, r * 2, r * 2);
  }
  const tex = new THREE.CanvasTexture(c);
  tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
  tex.colorSpace = THREE.SRGBColorSpace;
  tex.anisotropy = 8;
  return tex;
}

export function makeCloudTexture() {
  const w = 256;
  const h = 160;
  const c = document.createElement('canvas');
  c.width = w;
  c.height = h;
  const ctx = c.getContext('2d');
  const rng = mulberry32(417);
  for (let i = 0; i < 26; i++) {
    const x = w * (0.18 + rng() * 0.64);
    const y = h * (0.38 + rng() * 0.34);
    const r = 20 + rng() * 46;
    const g = ctx.createRadialGradient(x, y, 0, x, y, r);
    g.addColorStop(0, 'rgba(255,250,238,0.30)');
    g.addColorStop(0.55, 'rgba(246,243,232,0.15)');
    g.addColorStop(1, 'rgba(240,240,230,0)');
    ctx.fillStyle = g;
    ctx.fillRect(x - r, y - r, r * 2, r * 2);
  }
  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace;
  return tex;
}

import * as THREE from 'three';
import {
  fbm, smoothstep, smootherstep, clamp, lerp, damp, mulberry32, randRange, shortestAngle,
} from './utils.js';
import {
  makeToonGradient, makeGlowTexture, makeDotTexture, makePetalTexture,
  makeGrassTexture, makeCloudTexture,
} from './textures.js';

export const WATER_LEVEL = 2;
export const WORLD_EDGE = 760;
export const START_POSITION = new THREE.Vector3(-24, 152, 238);

const GATE_DEFS = [
  { name: 'Whisper of the Grass', pos: [0, 126, 78] },
  { name: 'The Lake’s Memory', pos: [-158, 82, 8] },
  { name: 'A Drift of Pollen', pos: [-292, 62, 96] },
  { name: 'The Sunken Bell', pos: [-300, 132, -118] },
  { name: 'Pine Song', pos: [-122, 166, -258] },
  { name: 'Cloud’s Cradle', pos: [62, 212, -332] },
  { name: 'Moonlit Feather', pos: [232, 146, -152] },
  { name: 'The Distant Kite', pos: [282, 112, 42] },
  { name: 'Homeward', pos: [152, 154, 212] },
];

export function terrainHeight(x, z) {
  const r = Math.hypot(x, z);
  let h = 46;
  h += 22 * fbm(x * 0.0032 + 12.7, z * 0.0032 + 5.1, 4);
  h += 34 * fbm(x * 0.0011 + 4.2, z * 0.0011 + 9.8, 3);

  // the high meadow that holds the Elder Tree
  const dt = Math.hypot(x - 40, z + 150);
  h += 42 * Math.exp(-(dt * dt) / (2 * 110 * 110));
  // a low, open bowl near the starting air
  const dv = Math.hypot(x - 20, z - 170);
  h -= 14 * Math.exp(-(dv * dv) / (2 * 180 * 180));

  // the lake — a deep blue basin to the west
  const dl = Math.hypot(x + 320, z - 70);
  h -= 124 * smootherstep(248, 34, dl);

  // encircling mountains
  const edge = smoothstep(430, 860, r);
  h += edge * (50 + 330 * fbm(x * 0.0022 + 30, z * 0.0022 + 6, 5));
  // a taller northern range
  const north = smoothstep(160, 640, -z) * smoothstep(250, 780, r);
  h += north * 115 * fbm(x * 0.0028 + 71, z * 0.0028 + 42, 4);

  return h;
}

function slopeAt(x, z) {
  const e = 3;
  const hx = terrainHeight(x + e, z) - terrainHeight(x - e, z);
  const hz = terrainHeight(x, z + e) - terrainHeight(x, z - e);
  return Math.hypot(hx, hz) / (2 * e);
}

const C = (hex) => new THREE.Color(hex);

export class World {
  constructor(scene, renderer, options = {}) {
    this.scene = scene;
    this.renderer = renderer;
    this.lowQuality = !!options.lowQuality;
    this.time = 0;
    this.rng = mulberry32(20241109);
    this.gates = [];
    this.collected = 0;
    this.blooming = false;
    this.bloomProgress = 0;
    this.petals = null;
    this.treeLight = null;
    this.windmillBlades = null;
    this.flock = null;
    this.islands = [];
    this.flowers = null;

    this.sunDir = new THREE.Vector3(-0.48, 0.42, -0.72).normalize();
    this.fogColor = C('#e9ddc1');
    this.glowTexture = makeGlowTexture(128);
    this.dotTexture = makeDotTexture(64);
    this.petalTexture = makePetalTexture(64);
    this.gradient = makeToonGradient([88, 154, 216, 255]);

    this.scene.fog = new THREE.FogExp2(this.fogColor, 0.00068);

    this._createSky();
    this._createLights();
    this._createTerrain();
    this._createWater();
    this._createTrees();
    this._createFlowers();
    this._createVillage();
    this._createGreatTree();
    this._createFloatingIslands();
    this._createClouds();
    this._createGates();
    this._createPollen();
    this._createFlock();
  }

  heightAt(x, z) {
    return terrainHeight(x, z);
  }

  _createSky() {
    const uniforms = {
      uSunDir: { value: this.sunDir },
      uZenith: { value: C('#4e88c2') },
      uHorizon: { value: C('#f4d7a4') },
      uHaze: { value: C('#f1e2c2') },
      uSunColor: { value: C('#ffe0a4') },
      uCloudColor: { value: C('#fff4e1') },
      uTime: { value: 0 },
    };
    const material = new THREE.ShaderMaterial({
      uniforms,
      side: THREE.BackSide,
      depthWrite: false,
      fog: false,
      vertexShader: /* glsl */`
        varying vec3 vDir;
        void main() {
          vDir = position;
          vec4 mv = modelViewMatrix * vec4(position, 1.0);
          gl_Position = projectionMatrix * mv;
        }
      `,
      fragmentShader: /* glsl */`
        uniform vec3 uSunDir;
        uniform vec3 uZenith;
        uniform vec3 uHorizon;
        uniform vec3 uHaze;
        uniform vec3 uSunColor;
        uniform vec3 uCloudColor;
        uniform float uTime;
        varying vec3 vDir;

        float hash(vec2 p) {
          p = fract(p * vec2(123.34, 456.21));
          p += dot(p, p + 45.32);
          return fract(p.x * p.y);
        }
        float noise(vec2 p) {
          vec2 i = floor(p), f = fract(p);
          f = f * f * (3.0 - 2.0 * f);
          return mix(mix(hash(i), hash(i + vec2(1.0, 0.0)), f.x),
                     mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), f.x), f.y);
        }
        float fbm(vec2 p) {
          float v = 0.0, a = 0.5;
          for (int i = 0; i < 5; i++) {
            v += a * noise(p);
            p = p * 2.03 + 11.7;
            a *= 0.5;
          }
          return v;
        }

        void main() {
          vec3 d = normalize(vDir);
          float h = d.y;
          float t = pow(clamp(h, 0.0, 1.0), 0.58);
          vec3 col = mix(uHorizon, uZenith, t);

          // warm haze hugging the horizon
          col = mix(col, uHaze, smoothstep(0.16, -0.08, h) * 0.86);

          // low, honeyed sun
          float s = max(dot(d, uSunDir), 0.0);
          col += uSunColor * pow(s, 850.0) * 3.0;
          col += uSunColor * pow(s, 22.0) * 0.24;
          col += uSunColor * pow(s, 4.0) * 0.10;

          // drifting high cirrus
          vec2 uv = d.xz / (max(abs(h), 0.04) + 0.09);
          float n = fbm(uv * 1.35 + vec2(uTime * 0.0022, uTime * 0.0011));
          float streaks = fbm(uv * vec2(0.5, 3.2) + 17.0);
          float cirrus = smoothstep(0.52, 0.82, n * 0.62 + streaks * 0.55);
          cirrus *= smoothstep(0.03, 0.24, h) * (0.35 + 0.65 * smoothstep(0.75, 0.15, h));
          col = mix(col, uCloudColor, cirrus * 0.38);

          // tiny warm bloom at the horizon line
          col += uHaze * smoothstep(0.03, 0.0, abs(h - 0.015)) * 0.12;

          float dither = fract(sin(dot(gl_FragCoord.xy, vec2(12.9898, 78.233))) * 43758.5453);
          col += (dither - 0.5) / 420.0;
          gl_FragColor = vec4(col, 1.0);
        }
      `,
    });
    this.skyUniforms = uniforms;
    this.sky = new THREE.Mesh(new THREE.SphereGeometry(3400, 48, 28), material);
    this.sky.frustumCulled = false;
    this.scene.add(this.sky);

    // sun glow sprite
    const sunSpriteMat = new THREE.SpriteMaterial({
      map: this.glowTexture,
      color: 0xffe3b0,
      transparent: true,
      opacity: 0.85,
      blending: THREE.AdditiveBlending,
      depthWrite: false,
      depthTest: false,
    });
    const sunSprite = new THREE.Sprite(sunSpriteMat);
    sunSprite.scale.setScalar(900);
    sunSprite.position.copy(this.sunDir).multiplyScalar(3000);
    sunSprite.renderOrder = -1;
    this.scene.add(sunSprite);
    this.sunSprite = sunSprite;
    this.sky.add(sunSprite);
  }

  _createLights() {
    const hemi = new THREE.HemisphereLight(0xbcd9ff, 0x53683d, 1.35);
    this.scene.add(hemi);

    const sun = new THREE.DirectionalLight(0xffd8a1, 2.65);
    sun.position.copy(this.sunDir).multiplyScalar(330);
    sun.castShadow = true;
    sun.shadow.mapSize.set(this.lowQuality ? 1024 : 2048, this.lowQuality ? 1024 : 2048);
    sun.shadow.camera.near = 10;
    sun.shadow.camera.far = 850;
    sun.shadow.camera.left = -180;
    sun.shadow.camera.right = 180;
    sun.shadow.camera.top = 180;
    sun.shadow.camera.bottom = -180;
    sun.shadow.bias = -0.0004;
    sun.shadow.normalBias = 1.2;
    this.scene.add(sun);
    this.scene.add(sun.target);
    this.sunLight = sun;

    // cool bounce from the opposite sky, no shadows
    const fill = new THREE.DirectionalLight(0x9ec6e8, 0.55);
    fill.position.set(0.7, 0.35, 0.8).multiplyScalar(300);
    this.scene.add(fill);

    // a faint amber bounce off the meadow
    const bounce = new THREE.DirectionalLight(0xffe6b0, 0.22);
    bounce.position.set(0.1, -1, 0.2).multiplyScalar(300);
    this.scene.add(bounce);
  }

  _createTerrain() {
    const size = 1900;
    const seg = this.lowQuality ? 200 : 300;
    const geo = new THREE.PlaneGeometry(size, size, seg, seg);
    geo.rotateX(-Math.PI / 2);

    const pos = geo.attributes.position;
    const count = pos.count;
    const colors = new Float32Array(count * 3);

    const sand = C('#d9c79a');
    const grassLight = C('#9cb06a');
    const grassMid = C('#6f9650');
    const grassDeep = C('#4f7849');
    const forest = C('#3f6841');
    const rock = C('#8c897a');
    const rockWarm = C('#a89f8a');
    const snow = C('#ece9da');
    const wild = C('#b3bd74');
    const tmp = new THREE.Color();

    for (let i = 0; i < count; i++) {
      const x = pos.getX(i);
      const z = pos.getZ(i);
      let h = terrainHeight(x, z);
      // soften the very outer lip so the world doesn't end in a wall
      pos.setY(i, h);

      const slope = slopeAt(x, z);
      const patch = fbm(x * 0.014 + 3.3, z * 0.014 + 9.1, 3);
      const fine = fbm(x * 0.055 + 4.2, z * 0.055 + 1.7, 2);

      if (h < WATER_LEVEL + 2.4) {
        tmp.copy(sand);
      } else {
        tmp.copy(grassMid);
        tmp.lerp(grassLight, smoothstep(0.42, 0.78, patch) * 0.85);
        tmp.lerp(grassDeep, smoothstep(0.55, 0.2, patch) * 0.55);
        tmp.lerp(forest, smoothstep(90, 230, h) * 0.55);
        if (patch > 0.66 && h < 140) tmp.lerp(wild, (patch - 0.66) * 0.55);
        tmp.offsetHSL(0, 0, (fine - 0.5) * 0.055);
      }

      // exposed rock on steep faces
      const rockMix = smoothstep(0.42, 0.9, slope);
      if (h > WATER_LEVEL + 3) {
        tmp.lerp(slope > 0.75 ? rockWarm : rock, rockMix * 0.85);
      }
      // high country
      if (h > 220) tmp.lerp(rock, smoothstep(220, 320, h) * 0.75);
      if (h > 315) tmp.lerp(snow, smoothstep(315, 400, h) * 0.9);

      // beach transition
      tmp.lerp(sand, smoothstep(WATER_LEVEL + 5.5, WATER_LEVEL + 0.3, h) * 0.9);

      colors[i * 3] = tmp.r;
      colors[i * 3 + 1] = tmp.g;
      colors[i * 3 + 2] = tmp.b;
    }
    geo.setAttribute('color', new THREE.BufferAttribute(colors, 3));
    geo.computeVertexNormals();

    const grassTex = makeGrassTexture();
    grassTex.repeat.set(68, 68);
    const mat = new THREE.MeshStandardMaterial({
      vertexColors: true,
      map: grassTex,
      roughness: 0.97,
      metalness: 0,
      dithering: true,
    });
    const mesh = new THREE.Mesh(geo, mat);
    mesh.receiveShadow = true;
    mesh.castShadow = false;
    this.scene.add(mesh);
    this.terrain = mesh;
  }

  _createWater() {
    const size = 2800;
    const seg = this.lowQuality ? 150 : 210;
    const geo = new THREE.PlaneGeometry(size, size, seg, seg);
    geo.rotateX(-Math.PI / 2);
    const pos = geo.attributes.position;
    const depths = new Float32Array(pos.count);
    for (let i = 0; i < pos.count; i++) {
      const x = pos.getX(i);
      const z = pos.getZ(i);
      depths[i] = clamp(WATER_LEVEL - terrainHeight(x, z), 0, 70);
      pos.setY(i, WATER_LEVEL);
    }
    geo.setAttribute('depth', new THREE.BufferAttribute(depths, 1));

    const mat = new THREE.ShaderMaterial({
      uniforms: {
        uTime: { value: 0 },
        uSunDir: { value: this.sunDir },
        uShallow: { value: C('#63b7ad') },
        uDeep: { value: C('#155a78') },
        uSkyTop: { value: C('#5c94c8') },
        uSkyHorizon: { value: C('#f2d5a4') },
        uSunColor: { value: C('#ffe6b5') },
        uFogColor: { value: this.fogColor },
        uFogDensity: { value: 0.00068 },
      },
      vertexShader: /* glsl */`
        uniform float uTime;
        attribute float depth;
        varying float vDepth;
        varying vec3 vWorld;
        varying vec3 vNormalW;
        void main() {
          vec3 p = position;
          float t = uTime;
          float a = 0.34;
          float w1 = sin(p.x * 0.055 + t * 0.85) * 0.55;
          float w2 = sin(p.z * 0.041 - t * 0.62 + 1.3) * 0.44;
          float w3 = sin((p.x + p.z) * 0.105 + t * 1.55) * 0.16;
          p.y += (w1 + w2 + w3) * a;

          float dx = cos(p.x * 0.055 + t * 0.85) * 0.055 * 0.55 * a
                   + cos((p.x + p.z) * 0.105 + t * 1.55) * 0.105 * 0.16 * a;
          float dz = cos(p.z * 0.041 - t * 0.62 + 1.3) * 0.041 * 0.44 * a
                   + cos((p.x + p.z) * 0.105 + t * 1.55) * 0.105 * 0.16 * a;
          vNormalW = normalize(vec3(-dx, 1.0, -dz));
          vDepth = depth;

          vec4 wp = modelMatrix * vec4(p, 1.0);
          vWorld = wp.xyz;
          gl_Position = projectionMatrix * viewMatrix * wp;
        }
      `,
      fragmentShader: /* glsl */`
        uniform float uTime;
        uniform vec3 uSunDir;
        uniform vec3 uShallow;
        uniform vec3 uDeep;
        uniform vec3 uSkyTop;
        uniform vec3 uSkyHorizon;
        uniform vec3 uSunColor;
        uniform vec3 uFogColor;
        uniform float uFogDensity;
        varying float vDepth;
        varying vec3 vWorld;
        varying vec3 vNormalW;

        float hash(vec2 p) {
          p = fract(p * vec2(233.34, 851.73));
          p += dot(p, p + 23.45);
          return fract(p.x * p.y);
        }

        void main() {
          vec3 V = normalize(cameraPosition - vWorld);
          vec3 N = normalize(vNormalW);
          float fres = pow(1.0 - max(dot(V, N), 0.0), 3.0);

          float d = smoothstep(0.0, 1.0, vDepth / 34.0);
          vec3 col = mix(uShallow, uDeep, d);

          vec3 R = reflect(-V, N);
          vec3 sky = mix(uSkyHorizon, uSkyTop, smoothstep(-0.05, 0.65, R.y));
          col = mix(col, sky, fres * 0.62);

          vec3 H = normalize(V + uSunDir);
          float spec = pow(max(dot(N, H), 0.0), 260.0);
          float sparkle = pow(max(dot(N, H), 0.0), 900.0);
          col += uSunColor * (spec * 1.15 + sparkle * 1.8);

          // little wind-ruffled sparkle flecks
          vec2 gp = floor(vWorld.xz * 1.3);
          float s = hash(gp);
          if (s > 0.982) {
            float tw = sin(uTime * 2.3 + s * 30.0) * 0.5 + 0.5;
            col += uSunColor * tw * 0.35 * smoothstep(0.0, 0.4, spec + 0.08);
          }

          // lace of foam where the lake breathes against the shore
          float foamBand = smoothstep(4.2, 0.35, vDepth);
          float ripple = sin(vWorld.x * 0.32 + vWorld.z * 0.27 + uTime * 1.7) * 0.5 + 0.5;
          float foam = foamBand * smoothstep(0.56, 0.94, ripple) * 0.42;
          col = mix(col, vec3(0.94, 0.97, 0.94), foam);

          float dist = length(cameraPosition - vWorld);
          float fogF = 1.0 - exp(-uFogDensity * uFogDensity * dist * dist);
          col = mix(col, uFogColor, clamp(fogF, 0.0, 1.0));

          gl_FragColor = vec4(col, 1.0);
        }
      `,
    });
    const mesh = new THREE.Mesh(geo, mat);
    mesh.receiveShadow = false;
    this.scene.add(mesh);
    this.water = mesh;
    this.waterUniforms = mat.uniforms;
  }

  _createTrees() {
    const rng = this.rng;
    const count = this.lowQuality ? 360 : 620;
    const trunkGeo = new THREE.CylinderGeometry(0.5, 0.95, 1, 6, 1);
    trunkGeo.translate(0, 0.5, 0);
    const canopyGeo = new THREE.IcosahedronGeometry(1, 1);

    const trunkMat = new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 1, flatShading: true });
    const canopyMat = new THREE.MeshToonMaterial({
      color: 0xffffff,
      gradientMap: this.gradient,
      roughness: 1,
      emissive: C('#20351f'),
      emissiveIntensity: 0.08,
    });

    const trees = [];
    let tries = 0;
    while (trees.length < count && tries < count * 14) {
      tries++;
      const a = rng() * Math.PI * 2;
      const rr = Math.sqrt(rng()) * 560;
      const x = Math.cos(a) * rr;
      const z = Math.sin(a) * rr;
      const h = terrainHeight(x, z);
      if (h < WATER_LEVEL + 7) continue;
      if (slopeAt(x, z) > 0.55) continue;
      if (Math.hypot(x - 40, z + 150) < 48) continue; // keep the Elder Tree's glade open
      if (Math.hypot(x - 150, z - 90) < 60) continue; // village
      if (Math.hypot(x - 20, z - 220) < 60) continue; // start clearing
      trees.push({ x, z, h, scale: randRange(rng, 0.7, 1.55) });
    }

    const trunkMesh = new THREE.InstancedMesh(trunkGeo, trunkMat, trees.length);
    const canopyMesh = new THREE.InstancedMesh(canopyGeo, canopyMat, trees.length * 3);
    trunkMesh.castShadow = true;
    trunkMesh.receiveShadow = true;
    canopyMesh.castShadow = true;
    canopyMesh.receiveShadow = true;

    const m = new THREE.Matrix4();
    const q = new THREE.Quaternion();
    const e = new THREE.Euler();
    const s = new THREE.Vector3();
    const p = new THREE.Vector3();
    const colors = [
      C('#3e6840'), C('#4d7a45'), C('#5c884b'), C('#719657'), C('#345b3d'), C('#829e5c'),
    ];
    const c = new THREE.Color();
    let ci = 0;

    trees.forEach((t, i) => {
      const trunkH = randRange(rng, 8, 17) * t.scale;
      const trunkW = randRange(rng, 0.55, 1.05) * t.scale;
      e.set(0, rng() * Math.PI * 2, 0);
      q.setFromEuler(e);
      p.set(t.x, t.h - 0.5, t.z);
      s.set(trunkW, trunkH, trunkW);
      m.compose(p, q, s);
      trunkMesh.setMatrixAt(i, m);
      c.copy(C('#6b5640')).offsetHSL(0, 0, (rng() - 0.5) * 0.08);
      trunkMesh.setColorAt(i, c);

      const baseR = randRange(rng, 4.2, 7.6) * t.scale;
      for (let k = 0; k < 3; k++) {
        const r = baseR * (1 - k * 0.14) * randRange(rng, 0.82, 1.12);
        const ox = (rng() - 0.5) * baseR * 0.72;
        const oz = (rng() - 0.5) * baseR * 0.72;
        const oy = trunkH * (0.9 + k * 0.11) + (rng() - 0.5) * 1.2;
        e.set(rng() * 0.3, rng() * Math.PI * 2, rng() * 0.3);
        q.setFromEuler(e);
        p.set(t.x + ox, t.h + oy, t.z + oz);
        s.set(r, r * randRange(rng, 0.7, 0.95), r * randRange(rng, 0.88, 1.1));
        m.compose(p, q, s);
        canopyMesh.setMatrixAt(ci, m);
        c.copy(colors[Math.floor(rng() * colors.length)]);
        c.offsetHSL((rng() - 0.5) * 0.018, 0, (rng() - 0.5) * 0.055);
        canopyMesh.setColorAt(ci, c);
        ci++;
      }
    });

    this.scene.add(trunkMesh);
    this.scene.add(canopyMesh);
    this.treeMeshes = [trunkMesh, canopyMesh];
  }

  _createFlowers() {
    const rng = mulberry32(5301);
    const count = this.lowQuality ? 900 : 2200;
    const positions = [];
    const colors = [];
    const palette = [C('#f4e9b0'), C('#eec5cc'), C('#f7f1dc'), C('#d8c56f'), C('#c9d8a0')];
    const c = new THREE.Color();
    let tries = 0;
    while (positions.length < count * 3 && tries < count * 20) {
      tries++;
      const a = rng() * Math.PI * 2;
      const rr = Math.sqrt(rng()) * 300;
      const x = Math.cos(a) * rr + 20;
      const z = Math.sin(a) * rr + 70;
      const h = terrainHeight(x, z);
      if (h < WATER_LEVEL + 5 || slopeAt(x, z) > 0.4) continue;
      positions.push(x, h + 0.55, z);
      c.copy(palette[Math.floor(rng() * palette.length)]);
      colors.push(c.r, c.g, c.b);
    }
    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
    geo.setAttribute('color', new THREE.Float32BufferAttribute(colors, 3));
    const mat = new THREE.PointsMaterial({
      size: 1.15,
      map: this.dotTexture,
      vertexColors: true,
      transparent: true,
      alphaTest: 0.25,
      depthWrite: true,
      sizeAttenuation: true,
    });
    const points = new THREE.Points(geo, mat);
    this.scene.add(points);
    this.flowers = points;
  }

  _createVillage() {
    const rng = mulberry32(88012);
    const group = new THREE.Group();
    const houseData = [
      [128, 88, 0.35], [152, 108, -0.2], [110, 112, 0.8], [172, 78, 0.1],
      [138, 62, -0.5], [96, 74, 0.4], [158, 128, 0.2],
    ];
    const wallMat = new THREE.MeshStandardMaterial({ color: 0xe7dbc0, roughness: 0.9, flatShading: false });
    const beamMat = new THREE.MeshStandardMaterial({ color: 0x5c4633, roughness: 0.95 });
    const roofMat = new THREE.MeshStandardMaterial({ color: 0x9d5a3f, roughness: 0.9, flatShading: true });
    const stoneMat = new THREE.MeshStandardMaterial({ color: 0x8b8574, roughness: 1 });

    houseData.forEach(([x, z, rot], i) => {
      const h = terrainHeight(x, z);
      if (h < WATER_LEVEL + 4) return;
      const w = randRange(rng, 7, 11);
      const d = randRange(rng, 7, 10);
      const wallH = randRange(rng, 5.5, 8);
      const house = new THREE.Group();
      house.position.set(x, h, z);
      house.rotation.y = rot;

      const base = new THREE.Mesh(new THREE.BoxGeometry(w * 1.06, 2, d * 1.06), stoneMat);
      base.position.y = 1;
      base.receiveShadow = true;
      base.castShadow = true;
      house.add(base);

      const walls = new THREE.Mesh(new THREE.BoxGeometry(w, wallH, d), wallMat);
      walls.position.y = 2 + wallH / 2;
      walls.castShadow = true;
      walls.receiveShadow = true;
      house.add(walls);

      // dark timber frame
      const beamGeo = new THREE.BoxGeometry(w * 1.01, 0.24, 0.24);
      for (let k = 0; k < 3; k++) {
        const beam = new THREE.Mesh(beamGeo, beamMat);
        beam.position.set(0, 2.8 + k * (wallH / 3), d / 2 + 0.07);
        house.add(beam);
        const beam2 = beam.clone();
        beam2.position.z = -d / 2 - 0.07;
        house.add(beam2);
      }

      const roof = new THREE.Mesh(new THREE.ConeGeometry(Math.max(w, d) * 0.84, randRange(rng, 4.5, 7), 4), roofMat);
      roof.position.y = 2 + wallH + 2.2;
      roof.rotation.y = Math.PI / 4;
      roof.castShadow = true;
      roof.receiveShadow = true;
      house.add(roof);

      const chimney = new THREE.Mesh(new THREE.BoxGeometry(1.2, 3.4, 1.2), stoneMat);
      chimney.position.set(w * 0.24, 2 + wallH + 3.2, -d * 0.16);
      chimney.castShadow = true;
      house.add(chimney);

      // warm windows
      const winMat = new THREE.MeshBasicMaterial({ color: 0xffdd99, transparent: true, opacity: 0.9 });
      const winGeo = new THREE.PlaneGeometry(1.15, 1.5);
      for (let k = 0; k < 2; k++) {
        const win = new THREE.Mesh(winGeo, winMat);
        win.position.set(-w * 0.22 + k * w * 0.44, 2 + wallH * 0.55, d / 2 + 0.06);
        house.add(win);
      }
      const door = new THREE.Mesh(new THREE.PlaneGeometry(1.6, 2.8), beamMat);
      door.position.set(0, 2 + 1.4, d / 2 + 0.06);
      house.add(door);

      group.add(house);
    });

    // windmill on the ridge above the village
    const wx = 94;
    const wz = 40;
    const wh = terrainHeight(wx, wz);
    const mill = new THREE.Group();
    mill.position.set(wx, wh, wz);
    const tower = new THREE.Mesh(new THREE.CylinderGeometry(3.6, 5.4, 22, 8), wallMat);
    tower.position.y = 11;
    tower.castShadow = true;
    tower.receiveShadow = true;
    mill.add(tower);
    const cap = new THREE.Mesh(new THREE.ConeGeometry(4.6, 5, 8), roofMat);
    cap.position.y = 24.4;
    cap.castShadow = true;
    mill.add(cap);
    const hub = new THREE.Mesh(new THREE.CylinderGeometry(0.6, 0.6, 2, 8), beamMat);
    hub.rotation.x = Math.PI / 2;
    hub.position.set(0, 21.5, 3.4);
    mill.add(hub);
    const blades = new THREE.Group();
    blades.position.set(0, 21.5, 4.6);
    for (let i = 0; i < 4; i++) {
      const arm = new THREE.Mesh(new THREE.BoxGeometry(1.2, 15, 0.3), beamMat);
      arm.position.set(0, 0, 0);
      arm.geometry.translate(0, 7.5, 0);
      arm.rotation.z = (i * Math.PI) / 2;
      arm.castShadow = true;
      blades.add(arm);
      const sail = new THREE.Mesh(new THREE.BoxGeometry(3.3, 11, 0.12), new THREE.MeshStandardMaterial({ color: 0xd8ceb4, roughness: 1, side: THREE.DoubleSide }));
      sail.position.set(1.6, 8, 0.1);
      const holder = new THREE.Group();
      holder.rotation.z = (i * Math.PI) / 2;
      holder.add(sail);
      blades.add(holder);
    }
    mill.add(blades);
    this.windmillBlades = blades;
    group.add(mill);

    // a few fences
    const postMat = beamMat;
    for (let i = 0; i < 22; i++) {
      const x = 112 + i * 2.3;
      const z = 138 + Math.sin(i * 0.4) * 2.5;
      const h = terrainHeight(x, z);
      if (h < WATER_LEVEL + 4) continue;
      const post = new THREE.Mesh(new THREE.BoxGeometry(0.22, 2.4, 0.22), postMat);
      post.position.set(x, h + 1.2, z);
      post.castShadow = true;
      group.add(post);
    }

    group.traverse((o) => {
      if (o.isMesh) o.frustumCulled = true;
    });
    this.scene.add(group);
    this.village = group;
  }

  _createGreatTree() {
    const gx = 40;
    const gz = -150;
    const gh = terrainHeight(gx, gz);
    const group = new THREE.Group();
    group.position.set(gx, gh, gz);

    const barkMat = new THREE.MeshStandardMaterial({ color: 0x6b513b, roughness: 1, flatShading: true });
    const trunkGeo = new THREE.CylinderGeometry(3.4, 12.5, 112, 12, 7);
    const tp = trunkGeo.attributes.position;
    for (let i = 0; i < tp.count; i++) {
      const y = tp.getY(i);
      const bend = Math.sin((y + 56) * 0.045) * (1 - Math.max(y, 0) / 70) * 1.6;
      tp.setX(i, tp.getX(i) + bend);
      tp.setZ(i, tp.getZ(i) + Math.cos(y * 0.05) * 0.7);
    }
    trunkGeo.computeVertexNormals();
    const trunk = new THREE.Mesh(trunkGeo, barkMat);
    trunk.position.y = 56;
    trunk.castShadow = true;
    trunk.receiveShadow = true;
    group.add(trunk);

    // roots
    for (let i = 0; i < 8; i++) {
      const a = (i / 8) * Math.PI * 2 + 0.3;
      const root = new THREE.Mesh(new THREE.CylinderGeometry(1.1, 3.2, 22, 6), barkMat);
      root.position.set(Math.cos(a) * 10, 4, Math.sin(a) * 10);
      root.rotation.z = Math.cos(a) * 0.8;
      root.rotation.x = Math.sin(a) * 0.8;
      root.castShadow = true;
      group.add(root);
    }

    // main branches
    const branchDirs = [
      [1, 0.4, 0.2, 0.8], [-1, 0.5, 0.25, 0.9], [0.2, 0.6, -1, 0.75], [-0.3, 0.5, 1, 0.65],
    ];
    branchDirs.forEach(([bx, by, bz, len]) => {
      const br = new THREE.Mesh(new THREE.CylinderGeometry(1.2, 3, 42 * len, 7), barkMat);
      br.position.set(bx * 11, 78 + by * 14, bz * 11);
      br.rotation.z = -bx * 0.75;
      br.rotation.x = bz * 0.7;
      br.castShadow = true;
      group.add(br);
    });

    // canopy: layered clouds of leaves
    this.treeCanopies = [];
    const rng = mulberry32(3221);
    const greens = [C('#4f7a46'), C('#5e8b4e'), C('#709a58'), C('#3f6a43'), C('#87a963'), C('#a3b970')];
    const blobGeo = new THREE.IcosahedronGeometry(1, 1);
    for (let i = 0; i < 22; i++) {
      const a = rng() * Math.PI * 2;
      const rad = randRange(rng, 4, 38);
      const y = randRange(rng, 84, 144) + (1 - rad / 40) * 10;
      const scale = randRange(rng, 15, 27) * (1 - rad / 90);
      const mat = new THREE.MeshToonMaterial({
        color: greens[i % greens.length].clone(),
        gradientMap: this.gradient,
        emissive: C('#1b2c1a'),
        emissiveIntensity: 0.12,
      });
      const blob = new THREE.Mesh(blobGeo, mat);
      blob.position.set(Math.cos(a) * rad, y, Math.sin(a) * rad);
      blob.scale.set(scale * randRange(rng, 0.9, 1.25), scale * randRange(rng, 0.62, 0.82), scale * randRange(rng, 0.9, 1.2));
      blob.rotation.set(rng() * 0.4, rng() * Math.PI * 2, rng() * 0.3);
      blob.castShadow = true;
      blob.receiveShadow = true;
      group.add(blob);
      this.treeCanopies.push({
        mesh: blob,
        baseColor: mat.color.clone(),
        baseScale: blob.scale.clone(),
      });
    }

    // torii at the roots
    const redMat = new THREE.MeshStandardMaterial({ color: 0xb64e36, roughness: 0.8, flatShading: true });
    const torii = new THREE.Group();
    torii.position.set(0, 0, 22);
    const postL = new THREE.Mesh(new THREE.CylinderGeometry(0.9, 1.15, 16, 7), redMat);
    postL.position.set(-5.2, 8, 0);
    const postR = postL.clone();
    postR.position.x = 5.2;
    const top = new THREE.Mesh(new THREE.BoxGeometry(16, 1.3, 1.2), redMat);
    top.position.y = 16.2;
    top.rotation.z = 0;
    const top2 = new THREE.Mesh(new THREE.BoxGeometry(13, 0.9, 1), redMat);
    top2.position.y = 13.6;
    [postL, postR, top, top2].forEach((m) => { m.castShadow = true; torii.add(m); });
    group.add(torii);

    this.scene.add(group);
    this.greatTree = group;
    this.greatTreeTop = new THREE.Vector3(gx, gh + 150, gz);

    // subtle warm light that wakes with the tree
    this.treeLight = new THREE.PointLight(0xffd69a, 0, 280, 2);
    this.treeLight.position.copy(this.greatTreeTop);
    this.scene.add(this.treeLight);
  }

  _createFloatingIslands() {
    const makeIsland = (x, y, z, radius) => {
      const group = new THREE.Group();
      group.position.set(x, y, z);

      const rockMat = new THREE.MeshStandardMaterial({ color: 0x7e7564, roughness: 1, flatShading: true });
      const topMat = new THREE.MeshStandardMaterial({ color: 0x6f8f4e, roughness: 1 });
      const deepMat = new THREE.MeshStandardMaterial({ color: 0x5a574c, roughness: 1, flatShading: true });

      const top = new THREE.Mesh(new THREE.CylinderGeometry(radius, radius * 1.02, 3.2, 26, 1), topMat);
      top.position.y = 0;
      top.castShadow = true;
      top.receiveShadow = true;
      group.add(top);

      const rim = new THREE.Mesh(new THREE.TorusGeometry(radius * 0.99, 1.2, 6, 28), rockMat);
      rim.rotation.x = Math.PI / 2;
      rim.position.y = -1.2;
      group.add(rim);

      const rockGeo = new THREE.ConeGeometry(radius * 0.95, radius * 2.15, 13, 5, false);
      const rp = rockGeo.attributes.position;
      for (let i = 0; i < rp.count; i++) {
        const vx = rp.getX(i);
        const vy = rp.getY(i);
        const vz = rp.getZ(i);
        const n = fbm(vx * 0.08 + 4.1, vz * 0.08 + vy * 0.04, 3) - 0.5;
        const t = clamp((radius * 1.05 - vy) / (radius * 2.1), 0, 1);
        rp.setX(i, vx * (1 + n * 0.16 * t));
        rp.setZ(i, vz * (1 + n * 0.16 * t));
        rp.setY(i, vy + n * 2.0 * t);
      }
      rockGeo.computeVertexNormals();
      const rock = new THREE.Mesh(rockGeo, deepMat);
      rock.position.y = -radius * 1.06 - 1.5;
      rock.rotation.z = Math.PI;
      rock.castShadow = true;
      rock.receiveShadow = true;
      group.add(rock);

      // hanging vines
      const vineMat = new THREE.MeshStandardMaterial({ color: 0x4e6b3d, roughness: 1, side: THREE.DoubleSide });
      for (let i = 0; i < 10; i++) {
        const a = (i / 10) * Math.PI * 2;
        const len = 9 + this.rng() * 20;
        const vine = new THREE.Mesh(new THREE.PlaneGeometry(0.5, len), vineMat);
        vine.position.set(Math.cos(a) * radius * 0.92, -len / 2 - 1, Math.sin(a) * radius * 0.92);
        vine.rotation.y = a;
        group.add(vine);
      }

      // trees
      for (let i = 0; i < 4; i++) {
        const a = this.rng() * Math.PI * 2;
        const rr = this.rng() * radius * 0.55;
        const tx = Math.cos(a) * rr;
        const tz = Math.sin(a) * rr;
        const th = 12 + this.rng() * 8;
        const trunk = new THREE.Mesh(new THREE.CylinderGeometry(0.5, 1, th, 6), new THREE.MeshStandardMaterial({ color: 0x634b37, roughness: 1, flatShading: true }));
        trunk.position.set(tx, 1.6 + th / 2, tz);
        trunk.castShadow = true;
        group.add(trunk);
        for (let k = 0; k < 3; k++) {
          const r = 4.5 + this.rng() * 3;
          const blob = new THREE.Mesh(new THREE.IcosahedronGeometry(r, 1), new THREE.MeshToonMaterial({
            color: new THREE.Color().setHSL(0.27 + this.rng() * 0.04, 0.32, 0.34 + this.rng() * 0.12),
            gradientMap: this.gradient,
          }));
          blob.position.set(tx + (this.rng() - 0.5) * 6, 1.6 + th + k * 3.2 + this.rng() * 2, tz + (this.rng() - 0.5) * 6);
          blob.castShadow = true;
          group.add(blob);
        }
      }

      // a little waterfall spilling into the sky
      const fallMat = new THREE.ShaderMaterial({
        transparent: true,
        depthWrite: false,
        side: THREE.DoubleSide,
        uniforms: { uTime: { value: 0 }, uOpacity: { value: 0.92 } },
        vertexShader: `varying vec2 vUv; void main(){ vUv = uv; gl_Position = projectionMatrix * modelViewMatrix * vec4(position,1.0); }`,
        fragmentShader: /* glsl */`
          uniform float uTime; uniform float uOpacity; varying vec2 vUv;
          float hash(vec2 p){ return fract(sin(dot(p, vec2(41.2, 289.1))) * 43758.5); }
          float noise(vec2 p){
            vec2 i=floor(p), f=fract(p); f=f*f*(3.0-2.0*f);
            return mix(mix(hash(i),hash(i+vec2(1,0)),f.x), mix(hash(i+vec2(0,1)),hash(i+vec2(1,1)),f.x),f.y);
          }
          void main(){
            float n = noise(vec2(vUv.x * 18.0, vUv.y * 4.0 + uTime * 2.2));
            float n2 = noise(vec2(vUv.x * 40.0 + 4.0, vUv.y * 10.0 + uTime * 4.0));
            float streak = smoothstep(0.42, 0.8, n * 0.7 + n2 * 0.5);
            float edge = smoothstep(0.0, 0.16, vUv.x) * smoothstep(1.0, 0.84, vUv.x);
            float fade = smoothstep(0.0, 0.1, vUv.y) * smoothstep(1.0, 0.55, vUv.y);
            vec3 col = mix(vec3(0.62, 0.80, 0.84), vec3(0.96, 0.99, 1.0), streak);
            gl_FragColor = vec4(col, streak * edge * fade * uOpacity);
          }
        `,
      });
      const fall = new THREE.Mesh(new THREE.PlaneGeometry(8, 96), fallMat);
      fall.position.set(radius * 0.52, -48, radius * 0.66);
      fall.rotation.y = -0.5;
      group.add(fall);

      const mist = new THREE.Sprite(new THREE.SpriteMaterial({
        map: this.glowTexture, color: 0xe9fbff, transparent: true, opacity: 0.42,
        depthWrite: false, blending: THREE.AdditiveBlending,
      }));
      mist.scale.setScalar(38);
      mist.position.set(radius * 0.52, -92, radius * 0.66);
      group.add(mist);

      group.userData.fall = fall;
      this.scene.add(group);
      this.islands.push({ group, x, y, z, radius, fall, mist });
    };

    makeIsland(-318, 212, -126, 38);
    makeIsland(292, 224, -18, 44);
  }

  _createClouds() {
    const rng = mulberry32(7777);
    this.clouds = [];
    const puffGeo = new THREE.SphereGeometry(1, 11, 8);
    const cloudMat = new THREE.MeshToonMaterial({
      color: 0xfffaf0,
      gradientMap: this.gradient,
      emissive: C('#9db4c8'),
      emissiveIntensity: 0.12,
      roughness: 1,
    });
    const hazeTex = makeCloudTexture();

    const defs = [
      [-240, 218, -330, 1.3], [180, 240, -360, 1.1], [420, 235, -120, 1.0],
      [-430, 205, 160, 1.15], [320, 210, 250, 0.9], [-100, 260, 380, 0.95],
      [40, 300, -520, 1.3], [-520, 280, -320, 1.05], [530, 290, 180, 0.9],
    ];

    defs.forEach(([cx, cy, cz, scale]) => {
      const group = new THREE.Group();
      group.position.set(cx, cy, cz);
      const puffs = 10 + Math.floor(rng() * 8);
      for (let i = 0; i < puffs; i++) {
        const a = rng() * Math.PI * 2;
        const rr = Math.sqrt(rng()) * 36 * scale;
        const puff = new THREE.Mesh(puffGeo, cloudMat);
        const s = (12 + rng() * 20) * scale;
        puff.position.set(Math.cos(a) * rr, (rng() - 0.42) * 16 * scale, Math.sin(a) * rr * 0.7);
        puff.scale.set(s * (0.8 + rng() * 0.6), s * (0.55 + rng() * 0.35), s * (0.8 + rng() * 0.6));
        puff.castShadow = false;
        puff.receiveShadow = false;
        group.add(puff);
      }
      const halo = new THREE.Sprite(new THREE.SpriteMaterial({
        map: hazeTex, color: 0xfff4df, transparent: true, opacity: 0.32,
        depthWrite: false, fog: true,
      }));
      halo.scale.set(200 * scale, 95 * scale, 1);
      halo.position.y = 2;
      group.add(halo);
      this.scene.add(group);
      this.clouds.push({ group, speed: 0.6 + rng() * 1.2, drift: rng() * Math.PI * 2 });
    });

    // soft, far-off cloud banks that sit on the horizon
    const bankDefs = [
      [-900, 155, -900, 520, 200, 0.55], [800, 175, -700, 600, 240, 0.5],
      [-1150, 165, 200, 500, 210, 0.45], [500, 145, 950, 620, 230, 0.42],
      [1050, 190, 300, 470, 190, 0.4],
    ];
    bankDefs.forEach(([x, y, z, w, h, o]) => {
      const sp = new THREE.Sprite(new THREE.SpriteMaterial({
        map: hazeTex, color: 0xffeed2, transparent: true, opacity: o, depthWrite: false, fog: true,
      }));
      sp.position.set(x, y, z);
      sp.scale.set(w, h, 1);
      this.scene.add(sp);
    });
  }

  _createGates() {
    const gateGeo = new THREE.TorusGeometry(7.4, 0.26, 8, 72);
    const innerGeo = new THREE.TorusGeometry(6.55, 0.07, 6, 64);
    const streamerGeo = new THREE.PlaneGeometry(0.42, 3.6);
    const wispGeo = new THREE.SphereGeometry(1.25, 16, 12);
    const glowMat = new THREE.SpriteMaterial({
      map: this.glowTexture, color: 0xffe9b4, transparent: true, opacity: 0.8,
      blending: THREE.AdditiveBlending, depthWrite: false,
    });
    const wispMat = new THREE.MeshBasicMaterial({ color: 0xfff6d9, toneMapped: false });
    const streamerMat = new THREE.MeshBasicMaterial({
      color: 0xf6e5c2, side: THREE.DoubleSide, transparent: true, opacity: 0.85,
      depthWrite: false,
    });
    const ringMat = new THREE.MeshBasicMaterial({
      color: 0xffeec2, transparent: true, opacity: 0.92, blending: THREE.AdditiveBlending,
      depthWrite: false, toneMapped: false,
    });
    const innerMat = new THREE.MeshBasicMaterial({
      color: 0xfff8e4, transparent: true, opacity: 0.5, blending: THREE.AdditiveBlending,
      depthWrite: false, toneMapped: false,
    });

    const beamMat = new THREE.ShaderMaterial({
      transparent: true,
      depthWrite: false,
      side: THREE.DoubleSide,
      blending: THREE.AdditiveBlending,
      uniforms: { uColor: { value: C('#ffe6b0') }, uTime: { value: 0 }, uOpacity: { value: 1 } },
      vertexShader: `varying vec2 vUv; varying vec3 vP; void main(){ vUv = uv; vP = position; gl_Position = projectionMatrix * modelViewMatrix * vec4(position,1.0); }`,
      fragmentShader: /* glsl */`
        uniform vec3 uColor; uniform float uTime; uniform float uOpacity;
        varying vec2 vUv;
        void main(){
          float v = vUv.y;
          float a = pow(1.0 - v, 2.4) * 0.20;
          a += smoothstep(0.9, 0.2, v) * 0.045;
          a *= 0.8 + 0.2 * sin(uTime * 1.6 + v * 10.0);
          gl_FragColor = vec4(uColor, a * uOpacity);
        }
      `,
    });

    GATE_DEFS.forEach((def, i) => {
      const [x, baseY, z] = def.pos;
      const ground = terrainHeight(x, z);
      const y = Math.max(baseY, ground + 26, WATER_LEVEL + 18);

      const container = new THREE.Group();
      container.position.set(x, y, z);

      const ring = new THREE.Group();
      const prev = i === 0 ? START_POSITION : new THREE.Vector3(...GATE_DEFS[i - 1].pos);
      const facing = new THREE.Vector3(prev.x - x, prev.y - y, prev.z - z).normalize();
      ring.quaternion.setFromUnitVectors(new THREE.Vector3(0, 0, 1), facing);
      container.add(ring);

      const torus = new THREE.Mesh(gateGeo, ringMat);
      ring.add(torus);
      const inner = new THREE.Mesh(innerGeo, innerMat);
      inner.rotation.z = 0.4;
      ring.add(inner);

      const halo = new THREE.Sprite(glowMat.clone());
      halo.material.opacity = 0.55;
      halo.scale.setScalar(34);
      halo.position.z = -0.6;
      ring.add(halo);

      // paper streamers tied to the ring
      const streamers = [];
      for (let k = 0; k < 10; k++) {
        const a = (k / 10) * Math.PI * 2;
        const s = new THREE.Mesh(streamerGeo, streamerMat);
        s.position.set(Math.cos(a) * 7.5, Math.sin(a) * 7.5, 0);
        s.rotation.z = a + Math.PI / 2;
        s.rotation.y = 0.2;
        ring.add(s);
        streamers.push({ mesh: s, phase: this.rng() * Math.PI * 2 });
      }

      const wisp = new THREE.Mesh(wispGeo, wispMat);
      const wispGlow = new THREE.Sprite(glowMat.clone());
      wispGlow.material.opacity = 0.95;
      wispGlow.scale.setScalar(16);
      wisp.add(wispGlow);
      ring.add(wisp);

      const beam = new THREE.Mesh(new THREE.CylinderGeometry(1.1, 2.2, 300, 10, 1, true), beamMat.clone());
      beam.position.y = 120;
      beam.renderOrder = 2;
      container.add(beam);

      this.scene.add(container);
      this.gates.push({
        index: i,
        name: def.name,
        position: new THREE.Vector3(x, y, z),
        container,
        ring,
        torus,
        inner,
        halo,
        wisp,
        wispGlow,
        beam,
        streamers,
        collected: false,
        phase: this.rng() * Math.PI * 2,
      });
    });
  }

  _createPollen() {
    const rng = mulberry32(9291);
    const count = this.lowQuality ? 320 : 720;
    const positions = new Float32Array(count * 3);
    const speeds = new Float32Array(count);
    for (let i = 0; i < count; i++) {
      positions[i * 3] = (rng() - 0.5) * 150;
      positions[i * 3 + 1] = (rng() - 0.5) * 100;
      positions[i * 3 + 2] = (rng() - 0.5) * 150;
      speeds[i] = 0.25 + rng() * 0.7;
    }
    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.BufferAttribute(positions, 3));
    const mat = new THREE.PointsMaterial({
      color: 0xffefc2,
      size: 0.85,
      map: this.dotTexture,
      transparent: true,
      opacity: 0.72,
      blending: THREE.AdditiveBlending,
      depthWrite: false,
      sizeAttenuation: true,
    });
    const points = new THREE.Points(geo, mat);
    points.frustumCulled = false;
    this.scene.add(points);
    this.pollen = points;
    this.pollenSpeeds = speeds;
  }

  _createFlock() {
    const group = new THREE.Group();
    const bodyMat = new THREE.MeshBasicMaterial({ color: 0x47544a });
    const wingMat = new THREE.MeshBasicMaterial({ color: 0x5b6858, side: THREE.DoubleSide });
    const birds = [];
    for (let i = 0; i < 9; i++) {
      const b = new THREE.Group();
      const body = new THREE.Mesh(new THREE.ConeGeometry(0.35, 2.2, 5), bodyMat);
      body.rotation.x = -Math.PI / 2;
      b.add(body);
      const wl = new THREE.Mesh(new THREE.PlaneGeometry(3.4, 0.7), wingMat);
      wl.position.x = -1.6;
      wl.rotation.x = -Math.PI / 2;
      const wr = wl.clone();
      wr.position.x = 1.6;
      b.add(wl, wr);
      const row = Math.ceil(i / 2);
      const side = i === 0 ? 0 : i % 2 === 0 ? 1 : -1;
      b.position.set(side * row * 3.4, (this.rng() - 0.5) * 2, row * 3.1);
      b.userData = { wl, wr, phase: this.rng() * 10 };
      group.add(b);
      birds.push(b);
    }
    group.position.set(-150, 155, 10);
    this.scene.add(group);
    this.flock = { group, birds, angle: 0 };
  }

  collectGate(gate) {
    if (gate.collected) return false;
    gate.collected = true;
    gate.container.visible = false;
    this.collected++;
    return true;
  }

  awakenTree() {
    if (this.blooming) return;
    this.blooming = true;
    this.bloomProgress = 0;
    this._createPetals();
  }

  _createPetals() {
    const count = 520;
    const positions = new Float32Array(count * 3);
    const seed = new Float32Array(count);
    const rng = mulberry32(1992);
    for (let i = 0; i < count; i++) {
      const a = rng() * Math.PI * 2;
      const r = Math.sqrt(rng()) * 100;
      positions[i * 3] = this.greatTree.position.x + Math.cos(a) * r;
      positions[i * 3 + 1] = this.greatTree.position.y + 100 + rng() * 100;
      positions[i * 3 + 2] = this.greatTree.position.z + Math.sin(a) * r;
      seed[i] = rng() * 100;
    }
    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.BufferAttribute(positions, 3));
    const mat = new THREE.PointsMaterial({
      size: 1.7,
      map: this.petalTexture,
      transparent: true,
      opacity: 0.92,
      depthWrite: false,
      alphaTest: 0.05,
      color: 0xffffff,
    });
    const petals = new THREE.Points(geo, mat);
    petals.frustumCulled = false;
    this.scene.add(petals);
    this.petals = { points: petals, seed };
  }

  reset() {
    this.collected = 0;
    this.blooming = false;
    this.bloomProgress = 0;
    this.gates.forEach((g) => {
      g.collected = false;
      g.container.visible = true;
      g.container.scale.setScalar(1);
    });
    if (this.petals) {
      this.scene.remove(this.petals.points);
      this.petals.points.geometry.dispose();
      this.petals.points.material.dispose();
      this.petals = null;
    }
    this.treeLight.intensity = 0;
    this.treeCanopies.forEach((t) => {
      t.mesh.material.color.copy(t.baseColor);
      t.mesh.material.emissive.set('#1b2c1a');
      t.mesh.material.emissiveIntensity = 0.12;
      t.mesh.scale.copy(t.baseScale);
    });
    this.treeBloom = 0;
  }

  nearestGate(from) {
    let best = null;
    let bestD = Infinity;
    for (const g of this.gates) {
      if (g.collected) continue;
      const d = from.distanceTo(g.position);
      if (d < bestD) { bestD = d; best = g; }
    }
    return best ? { gate: best, distance: bestD } : null;
  }

  hitIsland(p) {
    for (const is of this.islands) {
      const dx = p.x - is.x;
      const dz = p.z - is.z;
      if (dx * dx + dz * dz < (is.radius * 0.92) ** 2 && p.y < is.y + 2 && p.y > is.y - is.radius * 2.0) return true;
    }
    return false;
  }

  update(dt, time, birdPos, playerActive) {
    this.time = time;
    this.skyUniforms.uTime.value = time;
    this.waterUniforms.uTime.value = time;

    // sun & shadows follow the bird so nearby ground detail stays crisp
    const focus = birdPos;
    this.sunLight.position.set(focus.x + this.sunDir.x * 330, focus.y + this.sunDir.y * 330, focus.z + this.sunDir.z * 330);
    this.sunLight.target.position.set(focus.x, Math.max(focus.y - 120, 40), focus.z);
    this.sunLight.target.updateMatrixWorld();

    // clouds drift
    for (const c of this.clouds) {
      c.group.position.x += c.speed * dt;
      c.group.position.z += Math.sin(time * 0.04 + c.drift) * 0.16 * dt;
      if (c.group.position.x > 900) c.group.position.x = -900;
    }

    if (this.windmillBlades) this.windmillBlades.rotation.z += dt * 0.34;

    // gates breathe
    for (const g of this.gates) {
      if (g.collected) continue;
      const pulse = Math.sin(time * 1.2 + g.phase) * 0.5 + 0.5;
      g.halo.material.opacity = 0.36 + pulse * 0.3;
      g.halo.scale.setScalar(30 + pulse * 7);
      g.inner.rotation.z += dt * 0.22;
      g.wisp.position.y = Math.sin(time * 1.35 + g.phase) * 0.9;
      g.wisp.rotation.y += dt * 0.5;
      g.wispGlow.scale.setScalar(14 + pulse * 5);
      g.beam.material.uniforms.uTime.value = time;
      g.beam.material.uniforms.uOpacity.value = 0.75 + pulse * 0.35;
      g.streamers.forEach((s, k) => {
        s.mesh.rotation.y = 0.2 + Math.sin(time * 1.9 + s.phase) * 0.22;
        s.mesh.rotation.z = 0.2 * Math.sin(time * 2.4 + k);
      });
    }

    // floating islands
    for (const is of this.islands) {
      is.group.position.y = is.y + Math.sin(time * 0.25 + is.x * 0.01) * 1.6;
      is.fall.material.uniforms.uTime.value = time;
      is.mist.material.opacity = 0.32 + Math.sin(time * 0.8 + is.z) * 0.08;
    }

    // pollen drifts with the player
    if (this.pollen) {
      this.pollen.position.copy(birdPos);
      const arr = this.pollen.geometry.attributes.position.array;
      const sp = this.pollenSpeeds;
      for (let i = 0; i < sp.length; i++) {
        const ix = i * 3;
        arr[ix] += Math.sin(time * 0.35 + i) * 0.012 + 0.018 * sp[i];
        arr[ix + 1] += (0.02 + sp[i] * 0.03) * 0.25;
        arr[ix + 2] += Math.cos(time * 0.28 + i * 0.7) * 0.012;
        if (arr[ix] > 76) arr[ix] = -76;
        if (arr[ix] < -76) arr[ix] = 76;
        if (arr[ix + 1] > 58) arr[ix + 1] = -58;
        if (arr[ix + 1] < -58) arr[ix + 1] = 58;
        if (arr[ix + 2] > 76) arr[ix + 2] = -76;
        if (arr[ix + 2] < -76) arr[ix + 2] = 76;
      }
      this.pollen.geometry.attributes.position.needsUpdate = true;
    }

    // flock
    if (this.flock) {
      this.flock.angle += dt * 0.075;
      const a = this.flock.angle;
      this.flock.group.position.set(-150 + Math.cos(a) * 105, 155 + Math.sin(a * 1.8) * 9, 10 + Math.sin(a) * 105);
      this.flock.group.rotation.y = -a + Math.PI / 2;
      this.flock.birds.forEach((b) => {
        const flap = Math.sin(time * 5.2 + b.userData.phase) * 0.5 + 0.5;
        b.userData.wl.rotation.y = -0.2 + flap * 0.55;
        b.userData.wr.rotation.y = 0.2 - flap * 0.55;
        b.position.y += Math.sin(time * 2.2 + b.userData.phase) * 0.002;
      });
    }

    // petals & bloom
    if (this.blooming) {
      this.bloomProgress = Math.min(1, this.bloomProgress + dt * 0.28);
      const t = this.bloomProgress;
      this.treeLight.intensity = t * 5.5;
      this.treeCanopies.forEach((c, i) => {
        const target = new THREE.Color().setHSL(0.94, 0.52, 0.74 + (i % 4) * 0.035);
        c.mesh.material.color.copy(c.baseColor).lerp(target, smoothstep(0, 1, t));
        c.mesh.material.emissive.set('#e7a6b8');
        c.mesh.material.emissiveIntensity = t * 0.32;
        const s = 1 + Math.sin(t * Math.PI) * 0.08;
        c.mesh.scale.copy(c.baseScale).multiplyScalar(s);
      });
      if (this.petals) {
        const arr = this.petals.points.geometry.attributes.position.array;
        const seeds = this.petals.seed;
        for (let i = 0; i < seeds.length; i++) {
          const ix = i * 3;
          arr[ix] += Math.sin(time * 0.8 + seeds[i]) * dt * 2.2 + dt * 1.1;
          arr[ix + 1] -= dt * (1.3 + (seeds[i] % 1.7));
          arr[ix + 2] += Math.cos(time * 0.6 + seeds[i] * 1.3) * dt * 2.0;
          if (arr[ix + 1] < this.greatTree.position.y - 8) {
            arr[ix + 1] = this.greatTree.position.y + 130 + (seeds[i] % 70);
            arr[ix] = this.greatTree.position.x + (Math.random() - 0.5) * 150;
            arr[ix + 2] = this.greatTree.position.z + (Math.random() - 0.5) * 150;
          }
        }
        this.petals.points.geometry.attributes.position.needsUpdate = true;
      }
    }
  }
}

import * as THREE from 'three';
import { clamp, damp, smoothstep } from './utils.js';
import { makeToonGradient } from './textures.js';

function makeFeatherGeometry(length, width, tipDarken = 0) {
  const shape = new THREE.Shape();
  shape.moveTo(0, 0.05);
  shape.bezierCurveTo(length * 0.22, width * 1.0, length * 0.68, width * 0.84, length, 0.03);
  shape.bezierCurveTo(length * 0.74, -width * 0.56, length * 0.3, -width * 0.9, 0, -0.03);
  shape.closePath();
  const geo = new THREE.ShapeGeometry(shape, 10);
  geo.rotateX(-Math.PI / 2);

  const pos = geo.attributes.position;
  const colors = new Float32Array(pos.count * 3);
  const base = new THREE.Color(0xfffdf6);
  const tip = new THREE.Color(tipDarken > 0.5 ? 0x3d4544 : 0xd4d5cc);
  const c = new THREE.Color();
  for (let i = 0; i < pos.count; i++) {
    const t = clamp(pos.getX(i) / length, 0, 1);
    c.copy(base).lerp(tip, smoothstep(0.58, 1.0, t) * (tipDarken > 0.5 ? 0.95 : 0.6));
    colors[i * 3] = c.r;
    colors[i * 3 + 1] = c.g;
    colors[i * 3 + 2] = c.b;
  }
  geo.setAttribute('color', new THREE.BufferAttribute(colors, 3));
  return geo;
}

export class Bird {
  constructor(scene) {
    this.scene = scene;
    this.position = new THREE.Vector3();
    this.velocityForward = new THREE.Vector3(0, 0, -1);
    this.yaw = 0;
    this.pitch = 0;
    this.roll = 0;
    this.speed = 32;
    this.wind = 1;
    this.flapTimer = 0;
    this.flapCooldown = 0;
    this.flapPhase = 0;
    this.verticalKick = 0;
    this.bankInput = 0;
    this.pitchInput = 0;
    this.crashCooldown = 0;
    this.lastSafe = new THREE.Vector3();

    this._buildModel();

    this.group = new THREE.Group();
    this.model = new THREE.Group();
    this.group.add(this.model);
    this.scene.add(this.group);

    this.forward = new THREE.Vector3(0, 0, -1);
    this.euler = new THREE.Euler(0, 0, 0, 'YXZ');
    this.smoothHead = 0;
  }

  _buildModel() {
    const wingGradient = makeToonGradient([70, 140, 205, 255]);
    const white = new THREE.MeshToonMaterial({
      color: 0xfffdf5,
      gradientMap: wingGradient,
      emissive: 0x2b3038,
      emissiveIntensity: 0.045,
    });
    const cream = new THREE.MeshToonMaterial({
      color: 0xf7f0df,
      gradientMap: wingGradient,
    });
    const beakMat = new THREE.MeshStandardMaterial({ color: 0xe0a053, roughness: 0.55, metalness: 0.05 });
    const eyeMat = new THREE.MeshBasicMaterial({ color: 0x1b211f });
    const glintMat = new THREE.MeshBasicMaterial({ color: 0xffffff });
    const legMat = new THREE.MeshStandardMaterial({ color: 0xca8f4e, roughness: 0.7 });

    const bodyGroup = new THREE.Group();
    bodyGroup.position.y = 0;
    this.bodyGroup = bodyGroup;
    this.model.add(bodyGroup);

    // body
    const body = new THREE.Mesh(new THREE.SphereGeometry(1, 26, 18), white);
    body.scale.set(0.62, 0.66, 1.55);
    body.castShadow = true;
    body.receiveShadow = true;
    bodyGroup.add(body);

    // breast
    const breast = new THREE.Mesh(new THREE.SphereGeometry(0.62, 20, 14), cream);
    breast.scale.set(0.8, 0.86, 1.0);
    breast.position.set(0, -0.16, -0.45);
    breast.castShadow = true;
    bodyGroup.add(breast);

    // neck + head
    const head = new THREE.Group();
    head.position.set(0, 0.22, -1.16);
    this.head = head;
    bodyGroup.add(head);

    const neck = new THREE.Mesh(new THREE.SphereGeometry(0.42, 18, 14), cream);
    neck.scale.set(0.82, 1.15, 1.25);
    neck.position.set(0, 0.05, 0.16);
    neck.castShadow = true;
    head.add(neck);

    const skull = new THREE.Mesh(new THREE.SphereGeometry(0.4, 20, 16), white);
    skull.scale.set(0.9, 0.94, 1.05);
    skull.position.set(0, 0.36, -0.18);
    skull.castShadow = true;
    head.add(skull);

    const beak = new THREE.Mesh(new THREE.ConeGeometry(0.17, 0.72, 7), beakMat);
    beak.rotation.x = -Math.PI / 2;
    beak.position.set(0, 0.28, -0.72);
    beak.castShadow = true;
    head.add(beak);
    const beakLower = new THREE.Mesh(new THREE.ConeGeometry(0.1, 0.42, 6), beakMat);
    beakLower.rotation.x = -Math.PI / 2;
    beakLower.position.set(0, 0.17, -0.6);
    head.add(beakLower);

    // eyes
    for (const side of [-1, 1]) {
      const eye = new THREE.Mesh(new THREE.SphereGeometry(0.082, 12, 10), eyeMat);
      eye.position.set(side * 0.255, 0.46, -0.4);
      head.add(eye);
      const glint = new THREE.Mesh(new THREE.SphereGeometry(0.026, 8, 6), glintMat);
      glint.position.set(side * 0.278, 0.492, -0.44);
      head.add(glint);
    }

    // tail fan
    const tail = new THREE.Group();
    tail.position.set(0, 0.12, 1.34);
    this.tail = tail;
    bodyGroup.add(tail);
    const tailMats = [
      new THREE.MeshToonMaterial({ color: 0xfffdf5, gradientMap: wingGradient, side: THREE.DoubleSide }),
      new THREE.MeshToonMaterial({ color: 0xeeeadd, gradientMap: wingGradient, side: THREE.DoubleSide }),
    ];
    for (let i = -2; i <= 2; i++) {
      const f = new THREE.Mesh(makeFeatherGeometry(1.5 - Math.abs(i) * 0.14, 0.28, i === 0 ? 0 : 0.3), tailMats[Math.abs(i) % 2]);
      f.position.set(i * 0.16, 0, 0);
      f.rotation.y = i * 0.19;
      f.scale.set(1, 1, 1);
      f.castShadow = true;
      tail.add(f);
    }

    // tucked feet
    for (const side of [-1, 1]) {
      const leg = new THREE.Mesh(new THREE.CylinderGeometry(0.045, 0.05, 0.7, 5), legMat);
      leg.position.set(side * 0.22, -0.55, 0.55);
      leg.rotation.x = 0.9;
      bodyGroup.add(leg);
      const foot = new THREE.Mesh(new THREE.BoxGeometry(0.2, 0.04, 0.32), legMat);
      foot.position.set(side * 0.22, -0.74, 0.75);
      bodyGroup.add(foot);
    }

    // wings
    const featherMats = [
      new THREE.MeshToonMaterial({ vertexColors: true, gradientMap: wingGradient, side: THREE.DoubleSide }),
    ];
    const makeWing = () => {
      const wing = new THREE.Group();
      // shoulder covert
      const shoulder = new THREE.Mesh(new THREE.SphereGeometry(0.46, 16, 12), white);
      shoulder.scale.set(1.4, 0.5, 1.1);
      shoulder.position.set(0.22, 0.02, 0);
      shoulder.castShadow = true;
      wing.add(shoulder);

      const feathers = [];
      const count = 9;
      for (let i = 0; i < count; i++) {
        const t = i / (count - 1);
        const length = 1.5 + t * 2.55;
        const width = 0.24 + (1 - t) * 0.2;
        const geo = makeFeatherGeometry(length, width, i >= count - 3 ? 1 : 0.25);
        const f = new THREE.Mesh(geo, featherMats[0]);
        f.position.set(0.18 + i * 0.22, 0.02 + i * 0.012, -0.02 + i * 0.035);
        f.rotation.y = -0.05 - (1 - t) * 0.42;
        f.rotation.z = -0.02;
        f.castShadow = true;
        wing.add(f);
        feathers.push({ mesh: f, baseY: f.rotation.y, phase: i * 0.45 });
      }

      // a soft underwing layer
      const under = new THREE.Mesh(new THREE.SphereGeometry(1, 16, 10), cream);
      under.scale.set(1.5, 0.14, 0.7);
      under.position.set(0.8, -0.1, 0.1);
      under.castShadow = true;
      wing.add(under);

      wing.userData.feathers = feathers;
      return wing;
    };

    this.wingR = makeWing();
    this.wingR.position.set(0.3, 0.2, -0.12);
    this.wingR.scale.x = 1;
    bodyGroup.add(this.wingR);

    this.wingL = makeWing();
    this.wingL.position.set(-0.3, 0.2, -0.12);
    this.wingL.scale.x = -1;
    bodyGroup.add(this.wingL);

    this.model.traverse((o) => {
      if (o.isMesh) {
        o.castShadow = true;
        o.receiveShadow = false;
      }
    });
  }

  reset(x, y, z, yaw = 0) {
    this.position.set(x, y, z);
    this.yaw = yaw;
    this.pitch = -0.03;
    this.roll = 0;
    this.speed = 32;
    this.wind = 1;
    this.flapTimer = 0;
    this.flapPhase = 0;
    this.verticalKick = 0;
    this.crashCooldown = 0;
    this.lastSafe.copy(this.position);
    this.group.position.copy(this.position);
  }

  getForward(target = this.forward) {
    this.euler.set(this.pitch, this.yaw, 0, 'YXZ');
    return target.set(0, 0, -1).applyEuler(this.euler).normalize();
  }

  update(dt, input) {
    this.time = (this.time || 0) + dt;

    const turn = clamp(input.turn || 0, -1, 1);
    const pitchIn = clamp(input.pitch || 0, -1, 1);
    const boost = !!input.boost;
    const wantFlap = !!input.flap;

    this.bankInput = damp(this.bankInput, turn, 5.5, dt);
    this.pitchInput = damp(this.pitchInput, pitchIn, 4.0, dt);

    // banked turn
    const rollTarget = -this.bankInput * 0.82;
    this.roll = damp(this.roll, rollTarget, 3.6, dt);
    const turnRate = (0.42 + this.speed * 0.011) * (0.65 + 0.35 * Math.cos(this.pitch));
    this.yaw -= this.bankInput * turnRate * dt * 1.25;

    // pitch — a little nose-down trim, and a stronger tuck while boosting
    const pitchTarget = this.pitchInput * 0.66 - 0.055 + (boost ? -0.22 : 0);
    this.pitch = damp(this.pitch, pitchTarget, 2.8, dt);
    this.pitch = clamp(this.pitch, -1.0, 0.92);

    // energy: diving trades height for speed, climbing trades speed for height
    let targetSpeed = 31 + -this.pitch * 27 + (boost ? 15 : 0);
    targetSpeed = clamp(targetSpeed, 13, 74);
    this.speed = damp(this.speed, targetSpeed, 0.95, dt);

    this.flapCooldown = Math.max(0, this.flapCooldown - dt);
    if (wantFlap && this.flapCooldown <= 0 && this.wind > 0.06) {
      this.speed = Math.min(80, this.speed + 8.5);
      this.wind = Math.max(0, this.wind - 0.145);
      this.flapTimer = 0.86;
      this.flapCooldown = 0.32;
      this.verticalKick = Math.min(9, this.verticalKick + 6.2);
    }
    this.verticalKick = damp(this.verticalKick, 0, 2.4, dt);

    // wind recovers while gliding; faster while diving
    const recovery = this.pitch < -0.25 ? 0.13 : 0.048;
    if (this.flapTimer <= 0) this.wind = Math.min(1, this.wind + recovery * dt);

    this.getForward(this.velocityForward);
    this.position.addScaledVector(this.velocityForward, this.speed * dt);
    this.position.y += this.verticalKick * dt;

    // a barely-there drift, so the bird feels alive
    const drift = Math.sin(this.time * 0.9) * 0.0015;
    this.roll += drift;

    // pose
    this.group.position.copy(this.position);
    this.euler.set(this.pitch, this.yaw, this.roll, 'YXZ');
    this.group.quaternion.setFromEuler(this.euler);

    this.flapTimer = Math.max(0, this.flapTimer - dt);
    const flapping = this.flapTimer > 0;
    const flapSpeed = flapping ? Math.PI * 2 * 2.6 : Math.PI * 2 * 0.37;
    this.flapPhase += dt * flapSpeed;

    const amp = flapping ? 0.72 : 0.075;
    const base = 0.11;
    const wingAngle = base + Math.sin(this.flapPhase) * amp;
    const fold = smoothstep(43, 64, this.speed) * 0.5 + (boost ? 0.28 : 0) + clamp((this.speed - 70) / 20, 0, 0.22);
    const foldAngle = clamp(fold, 0, 0.88);

    this.wingR.rotation.z = wingAngle;
    this.wingL.rotation.z = wingAngle;
    this.wingR.rotation.y = -foldAngle;
    this.wingL.rotation.y = -foldAngle;
    this.wingR.rotation.x = Math.sin(this.flapPhase * 0.5) * 0.02;
    this.wingL.rotation.x = this.wingR.rotation.x;

    for (const side of [this.wingR, this.wingL]) {
      const f = side.userData.feathers;
      for (let i = 0; i < f.length; i++) {
        const feather = f[i];
        feather.mesh.rotation.y = feather.baseY + Math.sin(this.flapPhase + feather.phase) * 0.025 * (flapping ? 1 : 0.3) - foldAngle * 0.12;
        feather.mesh.rotation.z = -0.015 + Math.cos(this.flapPhase * 0.8 + feather.phase) * 0.008;
      }
    }

    const bob = Math.sin(this.flapPhase * 0.5) * (flapping ? 0.055 : 0.018);
    this.bodyGroup.position.y = bob;
    this.bodyGroup.rotation.z = -this.bankInput * 0.06;
    this.bodyGroup.rotation.x = Math.sin(this.time * 0.7) * 0.012;

    this.head.rotation.y = damp(this.head.rotation.y, -this.bankInput * 0.22, 3, dt) - this.bankInput * 0.06;
    this.head.rotation.x = damp(this.head.rotation.x, -this.pitch * 0.15, 3, dt);
    this.tail.rotation.y = damp(this.tail.rotation.y, this.bankInput * 0.24, 3, dt);
    this.tail.rotation.x = -this.pitch * 0.12 + Math.sin(this.time * 1.3) * 0.015;

    // remember a safe spot in case a cliff sneaks up
    const ground = this.world ? this.world.heightAt(this.position.x, this.position.z) : 0;
    if (this.position.y > ground + 34) {
      this.safeTimer = (this.safeTimer || 0) + dt;
      if (this.safeTimer > 0.7) {
        this.lastSafe.copy(this.position);
        this.safeTimer = 0;
      }
    } else {
      this.safeTimer = 0;
    }
  }

  respawn(world) {
    const safe = this.lastSafe;
    this.position.copy(safe);
    const ground = world.heightAt(safe.x, safe.z);
    this.position.y = Math.max(this.position.y, ground + 55, 70);
    this.speed = 34;
    this.pitch = 0;
    this.roll = 0;
    this.verticalKick = 0;
    this.flapTimer = 0.5;
    this.flapPhase = 0;
    this.wind = Math.min(1, this.wind + 0.25);
    this.group.position.copy(this.position);
  }

  faceTo(target, instant = false) {
    const dx = target.x - this.position.x;
    const dz = target.z - this.position.z;
    const yaw = Math.atan2(-dx, -dz);
    if (instant) this.yaw = yaw;
    else {
      let diff = yaw - this.yaw;
      while (diff > Math.PI) diff -= Math.PI * 2;
      while (diff < -Math.PI) diff += Math.PI * 2;
      this.yaw += diff * 0.01;
    }
  }
}

