const makeWing = () => {
  const wing = new THREE.Group();
  // broad, softly rounded wing membrane beneath the feathers
  const planform = new THREE.Shape();
  planform.moveTo(0.06, 0.58);
  planform.bezierCurveTo(1.4, 0.5, 3.0, 0.28, 3.95, 0.08);
  planform.bezierCurveTo(3.8, -0.34, 3.3, -0.68, 2.5, -0.94);
  planform.bezierCurveTo(1.7, -1.12, 0.8, -1.18, 0.12, -1.12);
  planform.closePath();
  const membraneGeo = new THREE.ShapeGeometry(planform, 16);
  membraneGeo.rotateX(-Math.PI / 2);
  const membrane = new THREE.Mesh(membraneGeo, new THREE.MeshToonMaterial({
    color: 0xe6e2d5,
    gradientMap: wingGradient,
    side: THREE.DoubleSide,
  }));
  membrane.position.y = -0.045;
  membrane.castShadow = true;
  wing.add(membrane);

  // shoulder covert
  const shoulder = new THREE.Mesh(new THREE.SphereGeometry(0.46, 16, 12), white);
  shoulder.scale.set(1.5, 0.42, 1.35);
  shoulder.position.set(0.28, 0.04, 0.1);
  shoulder.castShadow = true;
  wing.add(shoulder);

  const feathers = [];
  const count = 9;
  for (let i = 0; i < count; i++) {
    const t = i / (count - 1);
    const length = 1.65 + t * 2.65;
    const width = 0.32 + (1 - t) * 0.22;
    const variant = i >= count - 3 ? 2 : i === count - 4 ? 1 : 0;
    const geo = makeFeatherGeometry(length, width, variant);
    const f = new THREE.Mesh(geo, featherMats[0]);
    f.position.set(0.16 + i * 0.23, 0.045 + i * 0.012, -0.02 + i * 0.045);
    f.rotation.y = -0.06 - (1 - t) * 0.5;
    f.rotation.z = -0.02;
    f.castShadow = true;
    wing.add(f);
    feathers.push({ mesh: f, baseY: f.rotation.y, phase: i * 0.45 });
  }

